from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}
        self._next_id = 1

    def _overlaps(self, start1: datetime, end1: datetime,
                  start2: datetime, end2: datetime) -> bool:
        return start1 < end2 and start2 < end1

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        # Validate that the appointment is in the future
        if start <= now:
            raise ValueError("Cannot book an appointment in the past.")

        if end <= start:
            raise ValueError("End time must be after start time.")

        # Patient can have at most one upcoming appointment
        for appt in self._appointments.values():
            if (appt["patient"] == patient
                    and not appt["cancelled"]
                    and appt["end"] > now):
                raise ValueError(
                    f"Patient {patient!r} already has an upcoming appointment."
                )

        # Check doctor availability
        for appt in self._appointments.values():
            if appt["doctor"] == doctor and not appt["cancelled"]:
                if self._overlaps(start, end, appt["start"], appt["end"]):
                    raise ValueError(
                        f"Doctor {doctor!r} is not available in this time slot."
                    )
            elif appt["doctor"] == doctor and appt["cancelled"] and appt["blocked"]:
                # A cancelled appointment whose slot is still blocked
                if self._overlaps(start, end, appt["start"], appt["end"]):
                    raise ValueError(
                        f"Doctor {doctor!r} is not available in this time slot."
                    )

        appointment_id = self._next_id
        self._next_id += 1
        self._appointments[appointment_id] = {
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            "cancelled": False,
            "blocked": False,
        }
        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self._appointments:
            raise ValueError(f"Unknown appointment id: {appointment_id}")

        appt = self._appointments[appointment_id]
        if appt["cancelled"]:
            return

        appt["cancelled"] = True

        # If cancelled less than 24 hours before start, keep slot blocked
        if appt["start"] - now < timedelta(hours=24):
            appt["blocked"] = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        for appt in self._appointments.values():
            if appt["doctor"] != doctor:
                continue
            if appt["cancelled"] and not appt["blocked"]:
                continue
            if self._overlaps(start, end, appt["start"], appt["end"]):
                return False
        return True
